class CashFlowStatementService:
    def build_ias7_statement(self, org: Organization, date_from, date_to):
        """Generate IAS 7 cash flow statement"""
        transactions = Transaction.objects.filter(
            organization=org,
            created_at__gte=date_from,
            created_at__lte=date_to
        )

        operating = transactions.filter(ias7_classification='operating').aggregate(
            total=Sum('amount')
        )['total'] or 0
        investing = transactions.filter(ias7_classification='investing').aggregate(
            total=Sum('amount')
        )['total'] or 0
        financing = transactions.filter(ias7_classification='financing').aggregate(
            total=Sum('amount')
        )['total'] or 0

        return {
            'cash_flows': {
                'operating': operating,
                'investing': investing,
                'financing': financing,
                'net_change': operating + investing + financing,
            },
            'standard': 'IAS 7',
            'period': {'from': date_from, 'to': date_to}
        }

