import clamd
import logging
from django.core.exceptions import ValidationError

logger = logging.getLogger(__name__)

class MalwareScannerService:
    def __init__(self):
        try:
            self.clam = clamd.ClamdUnixSocket()
            self.available = self.clam.ping()
        except Exception as e:
            logger.warning('ClamAV not available: %s', e)
            self.available = False

    def scan_file(self, file_obj) -> bool:
        """Scan file for malware. Returns True if clean, False if infected."""
        if not self.available:
            logger.warning('Malware scanner unavailable, allowing file')
            return True  # Fail open if scanner unavailable

        try:
            scan_result = self.clam.instream(file_obj)
            if scan_result:
                found_key = list(scan_result.keys())[0]
                if scan_result[found_key][0] == 'FOUND':
                    logger.warning('Malware detected: %s', scan_result[found_key][1])
                    raise ValidationError(f"File contains malware: {scan_result[found_key][1]}")
            return True
        except ValidationError:
            raise
        except Exception as e:
            logger.error('Malware scan error: %s', e)
            raise ValidationError(f'File scan failed: {str(e)}')

